    public static void DecodeFrame(int frameIndex, uint[] pixels)
    {
        int dataOffset = FrameOffsets[frameIndex];
        int dataEnd = FrameOffsets[frameIndex + 1];
        int pixelOffset = 0;
        while (dataOffset < dataEnd)
        {
            int length = Runs[dataOffset++];
            uint color = Palette[Runs[dataOffset++]];
            for (int i = 0; i < length; i++)
                pixels[pixelOffset++] = color;
        }
    }
